pub fn cosine(a: &[f32], b: &[f32]) -> f32 {
    let dot: f32 = a.iter().zip(b).map(|(x, y)| x * y).sum();
    dot / (norm(a) * norm(b)).max(1e-12)
}

def slice_renormalize(vec: np.ndarray, dims: int) -> np.ndarray:
    sliced = vec[:dims]
    return sliced / max(float(np.linalg.norm(sliced)), 1e-12)

